create table if not exists public.members (id uuid primary key references auth.users(id) on delete cascade, name text not null, part text not null, created_at timestamptz not null default now());
create table if not exists public.events (id uuid primary key default gen_random_uuid(), title text not null, date date not null, time time not null, gather_time time not null, end_time time not null, venue text not null, venue_url text not null default '', memo text not null default '', kind text not null check (kind in ('合奏','分奏','本番')), created_by uuid not null references auth.users(id), created_at timestamptz not null default now());
create table if not exists public.responses (member_id uuid not null references auth.users(id) on delete cascade, event_id uuid not null references public.events(id) on delete cascade, status text not null check (status in ('yes','partial','no','maybe','none')), note text not null default '', primary key(member_id,event_id));
create table if not exists public.concert_settings (id text primary key, title text not null);
insert into public.concert_settings(id,title) values ('current','第48回定期演奏会') on conflict(id) do nothing;
alter table public.members enable row level security; alter table public.events enable row level security; alter table public.responses enable row level security; alter table public.concert_settings enable row level security;
create policy "members read" on public.members for select to authenticated using (true); create policy "member self write" on public.members for all to authenticated using (id=auth.uid()) with check (id=auth.uid());
create policy "events read" on public.events for select to authenticated using (true); create policy "events admin write" on public.events for all to authenticated using ((auth.jwt()->>'email')='takayuki.tsuchiya@gmail.com') with check ((auth.jwt()->>'email')='takayuki.tsuchiya@gmail.com');
create policy "responses read" on public.responses for select to authenticated using (true); create policy "responses self write" on public.responses for all to authenticated using (member_id=auth.uid()) with check (member_id=auth.uid());
create policy "settings read" on public.concert_settings for select to authenticated using (true); create policy "settings admin write" on public.concert_settings for all to authenticated using ((auth.jwt()->>'email')='takayuki.tsuchiya@gmail.com') with check ((auth.jwt()->>'email')='takayuki.tsuchiya@gmail.com');
